import { createContext, useContext, useState, useEffect, useCallback } from 'react';
// useSheets.js 的 apiFetch 收到 401（Google 登入憑證過期）時會發出這個事件
export const AUTH_EXPIRED_EVENT = 'pnl-auth-expired';
const AuthContext = createContext(null);
const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID || 'YOUR_CLIENT_ID_HERE';
const SCOPES = ['https://www.googleapis.com/auth/spreadsheets','https://www.googleapis.com/auth/drive.file','profile','email'].join(' ');
export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [gsiLoaded, setGsiLoaded] = useState(false);
  // 2026-10-25 新增：Google 登入憑證過期（約1小時）時設成 true，App 會在最上方顯示
  // 「登入已過期，請重新登入」，不會再讓畫面默默顯示 $0／尚無資料（見 useSheets.js 的 apiFetch）。
  const [expired, setExpired] = useState(false);
  const [expiresAt, setExpiresAt] = useState(null);
  useEffect(() => {
    const onExpired = () => setExpired(true);
    window.addEventListener(AUTH_EXPIRED_EVENT, onExpired);
    return () => window.removeEventListener(AUTH_EXPIRED_EVENT, onExpired);
  }, []);
  useEffect(() => {
    if (!expiresAt) return;
    const ms = expiresAt - Date.now();
    if (ms <= 0) { setExpired(true); return; }
    const t = setTimeout(() => setExpired(true), ms);
    return () => clearTimeout(t);
  }, [expiresAt]);
  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://accounts.google.com/gsi/client';
    script.async = true; script.defer = true;
    script.onload = () => setGsiLoaded(true);
    document.head.appendChild(script);
    const saved = localStorage.getItem('pnl_user');
    if (saved) {
      try {
        const { user: u, token: t, expires } = JSON.parse(saved);
        if (Date.now() < expires) { setUser(u); setToken(t); setExpiresAt(expires); }
        else localStorage.removeItem('pnl_user');
      } catch { localStorage.removeItem('pnl_user'); }
    }
    setLoading(false);
    return () => { if (document.head.contains(script)) document.head.removeChild(script); };
  }, []);
  // relogin=true：已經登入過、只是憑證過期，重新拿一次憑證就好（不用再跳一次授權同意畫面），
  // 畫面上正在填的表單內容不會被清掉。
  const login = useCallback((relogin = false) => {
    if (!gsiLoaded || !window.google) { alert('Google 登入尚未就緒'); return; }
    const client = window.google.accounts.oauth2.initTokenClient({
      client_id: GOOGLE_CLIENT_ID, scope: SCOPES,
      callback: async (resp) => {
        if (resp.error) return;
        const res = await fetch('https://www.googleapis.com/oauth2/v3/userinfo',
          { headers: { Authorization: `Bearer ${resp.access_token}` } });
        const profile = await res.json();
        const userData = { name: profile.name, email: profile.email, picture: profile.picture };
        const expires = Date.now() + 55*60*1000;
        setUser(userData); setToken(resp.access_token); setExpired(false); setExpiresAt(expires);
        localStorage.setItem('pnl_user', JSON.stringify({
          user: userData, token: resp.access_token, expires,
          scopes: resp.scope || ''
        }));
      },
    });
    client.requestAccessToken({ prompt: relogin === true ? '' : 'consent' });
  }, [gsiLoaded]);
  const logout = useCallback(() => {
    setUser(null); setToken(null); setExpired(false); setExpiresAt(null); localStorage.removeItem('pnl_user');
  }, []);
  return <AuthContext.Provider value={{ user, token, loading, login, logout, expired }}>{children}</AuthContext.Provider>;
}
export const useAuth = () => useContext(AuthContext);