import { useState, useEffect } from 'react';
import { useAccount } from '../context/AccountContext';
import { useSheets } from '../hooks/useSheets';
import { PERMISSIONS, DEFAULT_ROLES } from '../utils/config';

const PERM_LIST = Object.values(PERMISSIONS).filter(p => p.id !== 'MASTER');

function PermBadge({ perm, active }) {
  return (
    <span style={{
      fontSize:14, padding:'2px 7px', borderRadius:3, letterSpacing:1,
      background: active ? 'rgba(0,245,255,0.12)' : 'rgba(255,255,255,0.04)',
      color:      active ? 'var(--cyan)' : 'var(--muted)',
      border:     `1px solid ${active ? 'rgba(0,245,255,0.3)' : 'rgba(255,255,255,0.08)'}`,
    }}>
      {perm.label}
    </span>
  );
}

function AccountRow({ account, onEdit, isSelf }) {
  const role = Object.values(DEFAULT_ROLES).find(r =>
    r.perms.length === account.perms.length &&
    r.perms.every(p => account.perms.includes(p))
  );
  const isMaster = account.perms.includes('MASTER');
  return (
    <tr style={{ opacity: account.active ? 1 : 0.45 }}>
      <td>
        <div style={{ fontWeight:600, fontSize:18, color: isMaster ? 'var(--pink)' : 'var(--text)' }}>
          {account.name} {isSelf && <span style={{ fontSize:14, color:'var(--cyan)', marginLeft:4 }}>（你）</span>}
        </div>
        <div style={{ fontSize:14, color:'var(--muted)', marginTop:1 }}>{account.email}</div>
      </td>
      <td>
        {isMaster
          ? <span className="badge badge-danger">MASTER</span>
          : <span className="badge badge-blue">{role?.label || '自訂'}</span>
        }
      </td>
      <td>
        <div style={{ display:'flex', gap:4, flexWrap:'wrap' }}>
          {PERM_LIST.map(p => (
            <PermBadge key={p.id} perm={p} active={account.perms.includes(p.id)}/>
          ))}
        </div>
      </td>
      <td>
        <span className={`badge ${account.active ? 'badge-ok' : 'badge-gray'}`}>
          {account.active ? '啟用' : '停用'}
        </span>
      </td>
      <td>
        {!isMaster && (
          <button className="btn btn-ghost btn-sm" onClick={() => onEdit(account)}>
            ✏ 編輯
          </button>
        )}
      </td>
    </tr>
  );
}

function EditModal({ account, onSave, onClose, onDeactivate }) {
  const [perms, setPerms] = useState(account.perms || []);
  const [name,  setName]  = useState(account.name  || '');

  const togglePerm = (id) => {
    setPerms(prev => prev.includes(id) ? prev.filter(p => p!==id) : [...prev, id]);
  };
  const applyRole = (roleKey) => {
    setPerms([...DEFAULT_ROLES[roleKey].perms]);
  };

  return (
    <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,0.75)', zIndex:200, display:'flex', alignItems:'center', justifyContent:'center' }}>
      <div style={{ background:'var(--bg2)', border:'1px solid var(--border-strong)', borderRadius:6, padding:28, width:560, maxHeight:'85vh', overflowY:'auto' }}>
        <div style={{ fontFamily:'var(--title)', fontSize:20, fontWeight:700, color:'var(--cyan)', letterSpacing:3, marginBottom:18 }}>
          編輯帳號
        </div>

        <div style={{ marginBottom:14 }}>
          <label className="form-label">姓名</label>
          <input className="form-input" value={name} onChange={e => setName(e.target.value)}/>
        </div>
        <div style={{ marginBottom:4 }}>
          <div style={{ fontSize:14, color:'var(--muted)', marginBottom:6, letterSpacing:1 }}>{account.email}</div>
        </div>

        {/* 快速套用角色 */}
        <div style={{ marginBottom:16 }}>
          <label className="form-label">快速套用角色</label>
          <div style={{ display:'flex', gap:6, flexWrap:'wrap', marginTop:6 }}>
            {Object.entries(DEFAULT_ROLES).filter(([k]) => k !== 'master').map(([key, role]) => (
              <button key={key}
                className="btn btn-ghost btn-sm"
                style={{ borderColor:role.color, color:role.color }}
                onClick={() => applyRole(key)}>
                {role.label}
              </button>
            ))}
          </div>
        </div>

        {/* 權限勾選 */}
        <div style={{ marginBottom:20 }}>
          <label className="form-label">個別權限設定</label>
          <div style={{ display:'flex', flexDirection:'column', gap:8, marginTop:8 }}>
            {PERM_LIST.map(p => (
              <label key={p.id} style={{ display:'flex', alignItems:'center', gap:10, cursor:'pointer', padding:'8px 12px', borderRadius:4, background: perms.includes(p.id) ? 'rgba(0,245,255,0.06)' : 'rgba(255,255,255,0.02)', border:`1px solid ${perms.includes(p.id) ? 'rgba(0,245,255,0.25)' : 'var(--border)'}` }}>
                <input type="checkbox" checked={perms.includes(p.id)} onChange={() => togglePerm(p.id)}
                  style={{ width:14, height:14, accentColor:'var(--cyan)', cursor:'pointer' }}/>
                <div>
                  <div style={{ fontSize:17, fontWeight:600, color: perms.includes(p.id) ? 'var(--cyan)' : 'var(--text)' }}>{p.label}</div>
                  <div style={{ fontSize:14, color:'var(--muted)', marginTop:1 }}>{p.desc}</div>
                </div>
              </label>
            ))}
          </div>
        </div>

        <div style={{ display:'flex', gap:8 }}>
          <button className="btn btn-primary" style={{ flex:1, justifyContent:'center' }}
            onClick={() => onSave(account.email, { name, perms })}>
            ◈ 儲存權限設定
          </button>
          <button className="btn btn-danger btn-sm" onClick={() => onDeactivate(account.email)}>
            停用帳號
          </button>
          <button className="btn btn-ghost btn-sm" onClick={onClose}>取消</button>
        </div>
      </div>
    </div>
  );
}

export default function AccountPage() {
  const { accounts, currentAccount, addAccount, updateAccount, deactivateAccount, loadAccountsFromSheets } = useAccount();
  const { writeAccount, updateAccount: updateAccountSheets, readAccounts, readChangeLog, writeChangeLog } = useSheets();
  // 異動紀錄（2026-10-25 起存在 Google Sheets 的 change_log 分頁，重新整理也不會不見）
  const [logs, setLogs] = useState([]);
  const [logsLoading, setLogsLoading] = useState(false);
  const [logFilter, setLogFilter] = useState('');
  const loadLogs = () => { setLogsLoading(true); readChangeLog().then(l => { setLogs(l); setLogsLoading(false); }); };

  // 進入帳號管理頁面時從 Sheets 讀取最新帳號
  useEffect(() => {
    readAccounts().then(sheetAccounts => {
      if (sheetAccounts.length > 0) {
        loadAccountsFromSheets(sheetAccounts);
      }
    }).catch(e => console.warn('readAccounts failed:', e.message));
  }, []); // eslint-disable-line
  const [editing, setEditing]   = useState(null);
  const [showAdd, setShowAdd]   = useState(false);
  const [newAcc,  setNewAcc]    = useState({ email:'', name:'', perms:['VIEW_ALL'] });
  const [tab, setTab]           = useState('accounts'); // 'accounts' | 'logs'
  const [syncError, setSyncError] = useState('');

  // 這裡的畫面（accounts 狀態）是本機的暫存，真正對同事有效的是 Google Sheets 裡的資料。
  // 以前 Sheets 寫入失敗會完全沒提示，畫面看起來改好了，但同事登入時讀到的其實還是舊資料 —
  // 所以這裡失敗一定要跳出明顯的錯誤訊息，不能只是 console.warn。
  const handleSave = async (email, updates) => {
    const before = accounts.find(a => a.email === email);
    writeChangeLog('修改帳號', email, before ? { 姓名:before.name, 權限:(before.perms||[]).join(',') } : '', { 姓名:updates.name, 權限:(updates.perms||[]).join(',') });
    updateAccount(email, updates);
    setSyncError('');
    const result = await updateAccountSheets(email, updates);
    if (result && result.ok === false) {
      setSyncError(`「${email}」的權限修改：${result.error}。請重新整理這頁再試一次，如果一直失敗請確認這個帳號有出現在帳號 Google Sheet 裡。`);
    }
    setEditing(null);
  };

  // 停用帳號一定要同步寫回 Google Sheets ——
  // 之前這裡只改了畫面上的本機狀態，Sheets 裡那個人其實還是「啟用」，
  // 他下次登入（或在別台電腦登入）讀到的還是舊的、啟用中的資料，等於完全沒有被停用。
  const handleDeactivate = async (email) => {
    writeChangeLog('停用帳號', email, '啟用', '停用');
    deactivateAccount(email);
    setSyncError('');
    const result = await updateAccountSheets(email, { active:false });
    if (result && result.ok === false) {
      setSyncError(`停用「${email}」：${result.error}。這代表 Sheets 裡這個人可能還是「啟用」狀態，請重新整理這頁再試一次。`);
    }
    setEditing(null);
  };

  const handleAddAccount = async () => {
    if (!newAcc.email || !newAcc.name) return;
    writeChangeLog('新增帳號', newAcc.email, '', { 姓名:newAcc.name, 權限:newAcc.perms.join(',') });
    addAccount(newAcc);
    setSyncError('');
    // 寫入 Sheets
    try {
      await writeAccount({
        ...newAcc,
        role: Object.entries(DEFAULT_ROLES).find(([,r]) => JSON.stringify(r.perms.sort()) === JSON.stringify([...newAcc.perms].sort()))?.[0] || 'viewer',
        createdAt: new Date().toLocaleDateString('zh-TW'),
      });
    } catch(e) {
      console.warn('writeAccount failed:', e.message);
      setSyncError(`新增帳號「${newAcc.email}」沒有同步到 Google Sheets（${e.message}）。這個人現在登入還是不會有正確權限，請重新整理這頁再新增一次。`);
    }
    setNewAcc({ email:'', name:'', perms:['VIEW_ALL'] });
    setShowAdd(false);
  };

  const lf = logFilter.trim().toLowerCase();
  const importantLogs = lf ? logs.filter(l => [l.action, l.detail, l.name, l.email, l.time].some(v => String(v).toLowerCase().includes(lf))) : logs;

  return (
    <div>
      {syncError && (
        <div style={{ display:'flex', alignItems:'flex-start', gap:8, background:'rgba(255,0,110,0.08)', border:'1px solid rgba(255,0,110,0.3)', borderRadius:3, padding:'10px 14px', marginBottom:16, fontSize:14, color:'var(--pink)', lineHeight:1.6 }}>
          <span>⚠</span>
          <span style={{ flex:1 }}>{syncError}</span>
          <span style={{ cursor:'pointer', marginLeft:8 }} onClick={() => setSyncError('')}>✕</span>
        </div>
      )}
      {/* Tab 切換 */}
      <div style={{ display:'flex', gap:4, marginBottom:20, borderBottom:'1px solid var(--border)', paddingBottom:0 }}>
        {[
          { id:'accounts', label:`帳號管理 (${accounts.length})` },
          { id:'logs',     label:`異動紀錄` },
        ].map(t => (
          <button key={t.id}
            className={`btn btn-sm ${tab===t.id ? 'btn-primary' : 'btn-ghost'}`}
            style={{ borderRadius:'4px 4px 0 0', borderBottom:'none', marginBottom:-1 }}
            onClick={() => setTab(t.id)}>
            {t.label}
          </button>
        ))}
      </div>

      {/* ── 帳號列表 ── */}
      {tab === 'accounts' && (
        <div>
          <div className="card mb-16">
            <div className="card-title">
              系統帳號
              <button className="btn btn-primary btn-sm" onClick={() => setShowAdd(v => !v)}>
                {showAdd ? '✕ 取消' : '＋ 新增帳號'}
              </button>
            </div>

            {/* 新增帳號表單 */}
            {showAdd && (
              <div style={{ marginBottom:16, padding:14, background:'var(--bg3)', borderRadius:4, border:'1px solid rgba(0,245,255,0.3)' }}>
                <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10, marginBottom:10 }}>
                  <div>
                    <label className="form-label">Google 帳號（Email）</label>
                    <input className="form-input" placeholder="colleague@gmail.com"
                      value={newAcc.email} onChange={e => setNewAcc(p => ({ ...p, email:e.target.value }))}/>
                  </div>
                  <div>
                    <label className="form-label">姓名</label>
                    <input className="form-input" placeholder="同事名稱"
                      value={newAcc.name} onChange={e => setNewAcc(p => ({ ...p, name:e.target.value }))}/>
                  </div>
                </div>
                <div style={{ marginBottom:10 }}>
                  <label className="form-label">快速套用角色</label>
                  <div style={{ display:'flex', gap:6, marginTop:6 }}>
                    {Object.entries(DEFAULT_ROLES).filter(([k]) => k !== 'master').map(([key, role]) => (
                      <button key={key} className="btn btn-ghost btn-sm"
                        style={{ borderColor:role.color, color:role.color }}
                        onClick={() => setNewAcc(p => ({ ...p, perms:[...role.perms] }))}>
                        {role.label}
                      </button>
                    ))}
                  </div>
                </div>
                <div style={{ fontSize:14, color:'var(--muted)', marginBottom:10, letterSpacing:1 }}>
                  已選權限：{newAcc.perms.join(', ')}
                </div>
                <button className="btn btn-primary" onClick={handleAddAccount} style={{ justifyContent:'center', width:'100%' }}>
                  ◈ 確認新增帳號
                </button>
                <div style={{ fontSize:14, color:'var(--muted)', marginTop:8, letterSpacing:1 }}>
                  ◈ 帳號新增後，對方用該 Google Email 登入就會自動套用這裡的權限設定
                </div>
              </div>
            )}

            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th style={{ minWidth:160 }}>帳號</th>
                    <th>角色</th>
                    <th>權限</th>
                    <th>狀態</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {accounts.map(a => (
                    <AccountRow key={a.email} account={a}
                      isSelf={a.email === currentAccount?.email}
                      onEdit={setEditing}/>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* 權限說明 */}
          <div className="card" style={{ background:'rgba(0,245,255,0.02)' }}>
            <div className="card-title">權限模組說明</div>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:10 }}>
              {PERM_LIST.map(p => (
                <div key={p.id} style={{ padding:'10px 12px', background:'var(--bg3)', borderRadius:4, border:'1px solid var(--border)' }}>
                  <div style={{ fontSize:14, fontWeight:700, color:'var(--cyan)', marginBottom:3, letterSpacing:1 }}>{p.label}</div>
                  <div style={{ fontSize:14, color:'var(--muted)' }}>{p.desc}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ── 異動紀錄（Google Sheets 的 change_log 分頁）── */}
      {tab === 'logs' && (
        <LogsLoader onLoad={loadLogs}/>
      )}
      {tab === 'logs' && (
        <div className="card">
          <div className="card-title">
            異動紀錄
            <span>存在 Google Sheets「change_log」分頁：訂單、報表匯入、庫存、費用、客戶、商品、帳號的新增／修改／刪除</span>
          </div>
          <div style={{ display:'flex', gap:8, marginBottom:12 }}>
            <input className="form-input" placeholder="搜尋動作、內容、人員、日期…" value={logFilter} onChange={e => setLogFilter(e.target.value)}/>
            <button className="btn btn-ghost btn-sm" onClick={loadLogs} disabled={logsLoading}>{logsLoading ? '讀取中…' : '↻ 重新整理'}</button>
          </div>
          {importantLogs.length === 0
            ? (
              <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)' }}>
                <div style={{ fontSize:30, marginBottom:8 }}>◻</div>
                <div style={{ fontSize:14, letterSpacing:1 }}>{logsLoading ? '讀取中…' : '尚無異動紀錄'}</div>
              </div>
            ) : (
              <div className="table-wrap">
                <table>
                  <thead>
                    <tr><th>時間</th><th>帳號</th><th>動作</th><th>內容</th><th>修改前</th><th>修改後</th></tr>
                  </thead>
                  <tbody>
                    {importantLogs.slice(0, 300).map((log, i) => (
                      <tr key={i}>
                        <td style={{ fontSize:14, color:'var(--muted)', whiteSpace:'nowrap' }}>{log.time}</td>
                        <td>
                          <div style={{ fontSize:16, fontWeight:600 }}>{log.name}</div>
                          <div style={{ fontSize:13, color:'var(--muted)' }}>{log.email}</div>
                        </td>
                        <td><span className="badge badge-blue">{log.action}</span></td>
                        <td style={{ fontSize:15, maxWidth:220, wordBreak:'break-all' }}>{log.detail}</td>
                        <td style={{ fontFamily:'var(--mono)', fontSize:12, color:'var(--pink)', maxWidth:260, wordBreak:'break-all' }}>{log.before || '–'}</td>
                        <td style={{ fontFamily:'var(--mono)', fontSize:12, color:'var(--green)', maxWidth:260, wordBreak:'break-all' }}>{log.after || '–'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {importantLogs.length > 300 && <div style={{ fontSize:13, color:'var(--muted)', padding:8 }}>只顯示最新 300 筆，完整紀錄請直接看 Google Sheets 的 change_log 分頁</div>}
              </div>
            )
          }
        </div>
      )}

      {/* 編輯 Modal */}
      {editing && (
        <EditModal account={editing}
          onSave={handleSave}
          onClose={() => setEditing(null)}
          onDeactivate={handleDeactivate}/>
      )}
    </div>
  );
}
// 切到「異動紀錄」分頁時讀一次
function LogsLoader({ onLoad }) {
  useEffect(() => { onLoad(); }, []); // eslint-disable-line
  return null;
}
