import { useState, useEffect, useCallback, useMemo } from 'react';
import { fmt, todayISO } from '../utils/format';
import { useSheets } from '../hooks/useSheets';
import { CustomerSearch, CustomerModal } from './CrmPage';
import { useCustomer } from '../context/CustomerContext';
import { printInvoice } from '../utils/invoice';
import { expandToUnits, diffUnits, unitsToStockDeltas, erpSalesDate } from '../utils/salesCalc';

const CHANNELS = ['官網','momo','蝦皮','經銷','現場','其他'];
const EMPTY_ITEM = (kind = '一般') => ({code:'',name:'',qty:1,price:0,cost:0,kind});
// 品項類型（2026-10-26 新增）：公關品、退換是免費給出去的貨——單價固定 0（不算營收），
// 但一樣扣庫存、成本一樣算進銷貨成本（送出去的貨是真的成本）。
// 退回入庫（2026-10-26 新增）：客人退回來的貨，開單時一起加回庫存。存進 Sheets 時數量存成負數，
// 這樣扣庫存的計算會自然變成「加回」、銷貨成本也會自然扣回（貨回到倉庫），銷貨總表的銷售數量也會扣掉；
// 畫面上輸入、顯示一律用正數。
const ITEM_KINDS = ['一般', '公關品', '退換', '退回入庫'];
const isFree = it => it.kind === '公關品' || it.kind === '退換' || it.kind === '退回入庫';
const isReturn = it => it.kind === '退回入庫';
const PAGE_SIZE = 50;

// 把各種舊日期格式（例如 9/23 之前存的「2026/9/23」）轉成 <input type="date"> 吃得下的
// YYYY-MM-DD。轉不出來就回傳空字串，送出時會要求重新選日期，不會偷偷改成今天。
function toISODate(v) {
  const m = String(v || '').trim().match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (!m) return '';
  return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
}

export default function OrderPage() {
  const { customers, addCustomer, refreshCustomers } = useCustomer();
  const { writeOrder, readProducts, writeCustomer, readOrdersGrouped, deleteOrder, updateOrder,
          readPlatformData, readCodeMap, applyStockDeltas, writeChangeLog } = useSheets();

  // 商品清單改成即時從 Google Sheets 的商品總表讀取——
  // 之前這裡是寫死的固定清單，庫存管理新增的新商品在這裡看不到，
  // 而且商品成本如果之後在商品總表改過，這裡算出來的毛利還是用舊的、寫死的成本。
  const [productList, setProductList] = useState([]);
  const [codeMap, setCodeMap] = useState({});
  const [erpRows, setErpRows] = useState([]); // 經銷報表出貨紀錄（自動帶「這個客戶上次的成交價」用）
  useEffect(() => {
    readProducts().then(list => setProductList(list)).catch(() => {});
    readCodeMap().then(m => setCodeMap(m || {})).catch(() => {});
    readPlatformData('erp_raw').then(r => setErpRows(r || [])).catch(() => {});
  }, []); // eslint-disable-line
  // 下拉選單只列商品總表真的有建檔的代號＋只在套組成分表的套組（readProducts 會一起回傳）
  const sellable = productList;

  // 成本對照（代號→含稅成本）：從 Sheets 載入的歷史訂單沒有存成本，顯示毛利/編輯時用這個補
  const costMap = useMemo(() => {
    const m = {};
    productList.forEach(p => { m[p.code] = Number(p.cost) || 0; });
    return m;
  }, [productList]);

  const [items, setItems] = useState([EMPTY_ITEM()]);
  const [discount, setDiscount] = useState(0); // 整張訂單的折扣金額（跟上面選的含稅/未稅同一個基礎）
  const [channel, setChannel] = useState('經銷');
  // 開立日期：之前固定用「今天」，沒辦法補開之前的單或排未來的單，改成可以手動選日期，
  // 預設還是今天，不用每次都自己點。
  const [orderDate, setOrderDate] = useState(() => todayISO());
  const [customer, setCustomer] = useState(null);   // selected customer object
  const [customerName, setCustomerName] = useState('');
  const [note, setNote] = useState('');
  const [taxType, setTaxType] = useState('taxed');
  // 經銷商三個欄位
  const [dealerShort, setDealerShort] = useState('');  // 簡稱
  const [dealerTaxId, setDealerTaxId] = useState('');  // 統編
  const [dealerTitle, setDealerTitle] = useState('');  // 抬頭
  const [dealerSuggestions, setDealerSuggestions] = useState([]);
  const [showDealerDrop, setShowDealerDrop] = useState(false); // 'taxed' | 'untaxed'
  // ── 訂單紀錄：2026-10-25 起改成真的從 Google Sheets 的 orders 分頁讀取「全部歷史訂單」──
  // 之前這裡只是 useState([])，只會顯示「這次打開頁面之後」建立的訂單，重新整理就清空，
  // 也沒辦法點擊修改或刪除（Willie 回報問題1）。
  const [orders, setOrders] = useState([]);
  const [ordersLoading, setOrdersLoading] = useState(true);
  const [ordersError, setOrdersError] = useState('');
  const [search, setSearch] = useState('');
  const [showCount, setShowCount] = useState(PAGE_SIZE);
  const [editingId, setEditingId] = useState(null);           // 正在修改的訂單編號（null＝新增模式）
  const [editCustomerId, setEditCustomerId] = useState(null); // 修改時保留原本的客戶ID（CRM 還沒載入也不會被洗掉）
  const [editingOriginal, setEditingOriginal] = useState(null); // 修改前的那張訂單（算庫存要補回/多扣多少、寫異動紀錄用）
  const [copiedFrom, setCopiedFrom] = useState(null);         // 一鍵複製：從哪張訂單複製來的
  const [stockNotice, setStockNotice] = useState('');         // 扣庫存的結果提示
  const [submitting, setSubmitting] = useState(false);
  const [busyId, setBusyId] = useState(null);                 // 正在刪除的訂單
  const [saved, setSaved] = useState(false);
  const [showNewCustomer, setShowNewCustomer] = useState(false);
  const [syncError, setSyncError] = useState('');

  const loadOrders = useCallback(async () => {
    setOrdersLoading(true);
    setOrdersError('');
    try {
      setOrders(await readOrdersGrouped());
    } catch(e) {
      setOrdersError(`讀取 Google Sheets 的訂單紀錄失敗（${e.message}），請重新整理頁面再試一次。`);
    }
    setOrdersLoading(false);
  }, [readOrdersGrouped]);
  useEffect(() => { loadOrders(); }, []); // eslint-disable-line

  const resetForm = () => {
    setItems([EMPTY_ITEM()]);
    setDiscount(0);
    setCustomer(null); setCustomerName(''); setNote('');
    setDealerShort(''); setDealerTaxId(''); setDealerTitle('');
    setOrderDate(todayISO());
    setEditingId(null); setEditCustomerId(null); setEditingOriginal(null); setCopiedFrom(null);
  };

  // 把一張訂單的內容帶回左邊表單（修改、複製共用）
  const loadIntoForm = (o) => {
    setEditCustomerId(o.customerId || null);
    setChannel(o.channel || '經銷');
    const c = o.customerId ? customers.find(x => x.id === o.customerId) : null;
    setCustomer(c || null);
    setCustomerName(o.customer || '');
    setDealerShort(o.dealerShort || '');
    setDealerTaxId(o.dealerTaxId || '');
    setDealerTitle(o.dealerTitle || '');
    setNote(o.note || '');
    setTaxType(o.taxType || 'taxed');
    setItems(o.items.length
      ? o.items.map(it => ({ ...it, qty: Math.abs(Number(it.qty) || 0), kind: it.kind || '一般', cost: costMap[it.code] || 0 }))
      : [EMPTY_ITEM()]);
    setDiscount(o.discount || 0);
    setSyncError('');
    setStockNotice('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 點擊訂單紀錄的某一列 → 進入「修改」模式（訂單編號不變）
  const startEdit = (o) => {
    loadIntoForm(o);
    setEditingId(o.id);
    setEditingOriginal(o);
    setCopiedFrom(null);
    setOrderDate(toISODate(o.date));
  };

  // 一鍵複製（Willie 回報問題4）：把整張訂單的客戶、管道、品項、單價、備註帶回表單，
  // 但當成「新訂單」（新的訂單編號），開立日期改成今天，送出後原本那張完全不受影響。
  const startCopy = (o) => {
    loadIntoForm(o);
    setEditingId(null);
    setEditingOriginal(null);
    setCopiedFrom(o.id);
    setOrderDate(todayISO());
  };

  // 訂單內容摘要（寫異動紀錄用）
  const summarize = (o) => o ? ({
    日期: o.date, 管道: o.channel, 客戶: o.customer,
    品項: (o.items || []).map(it => `${it.code}×${it.qty}@${it.price}${it.kind && it.kind !== '一般' ? `（${it.kind}）` : ''}`).join('、'),
    折扣: o.discount || 0,
    含稅金額: o.taxedTotal ?? undefined, 金額類型: o.taxType === 'untaxed' ? '未稅' : '含稅',
  }) : '';

  // 依品項算出要扣的單品數量（套組依套組成分表拆成單品）
  const unitsOf = (its) => expandToUnits((its || []).map(it => ({ code: it.code, qty: Number(it.qty) || 0 })), productList, codeMap);

  // 實際更新庫存＋整理成畫面提示
  const applyStock = async (units, type, note) => {
    const deltas = unitsToStockDeltas(units);
    if (Object.keys(deltas).length === 0) return '';
    const r = await applyStockDeltas(deltas, type, note);
    if (!r.ok) return `⚠ ${r.error}——訂單已經存好了，但庫存沒有跟著更新，請到「庫存管理」用盤點調整補正。`;
    const parts = r.applied.map(a => `${a.code} ${a.delta > 0 ? '+' : ''}${a.delta}（${a.oldStock}→${a.newStock}）`);
    return `庫存已更新：${parts.join('、')}`;
  };

  const handleDelete = async (o) => {
    if (!window.confirm(`確定要刪除訂單 ${o.id}（${o.customer}，${fmt.currency(o.taxedTotal)}）嗎？\n刪除後會直接從 Google Sheets 移除，沒辦法復原。`)) return;
    setBusyId(o.id);
    setSyncError('');
    const r = await deleteOrder(o.id);
    setBusyId(null);
    if (!r.ok) { setSyncError(r.error); return; }
    // 這張訂單當初有扣過庫存，刪除時補回去（功能上線前的舊訂單當初沒扣，就不補）
    let notice = '';
    if (o.stockDeducted) {
      const u = unitsOf(o.items);
      const back = {}; Object.entries(u.units).forEach(([k, v]) => { back[k] = -v; }); // 負的「賣出量」＝補回
      notice = await applyStock(back, '刪除訂單回補', `刪除訂單 ${o.id}`);
    }
    setStockNotice(notice);
    writeChangeLog('刪除訂單', o.id, summarize(o), '');
    if (editingId === o.id) resetForm();
    await loadOrders();
    refreshCustomers().catch(() => {});
  };

  const addItem = (kind = '一般') => setItems(prev => [...prev, EMPTY_ITEM(kind)]);
  // 切換品項類型：改成公關品/退換時單價歸 0；改回一般時重新帶建議售價
  const setItemKind = (idx, kind) => setItems(prev => prev.map((it, i) => {
    if (i !== idx) return it;
    if (kind !== '一般') return { ...it, kind, price: 0, priceSource: '' };
    const p = productList.find(p => p.code === it.code);
    const sug = p ? suggestPrice(p) : { price: 0, source: '' };
    return { ...it, kind, price: sug.price, priceSource: sug.price ? sug.source : '' };
  }));
  const removeItem = idx => setItems(prev => prev.filter((_,i) => i!==idx));

  // ── 自動帶入售價（2026-10-25 新增）──────────────────────────
  // 選商品時依序找：①這個客戶上次買這個商品的成交價（手動開單＋經銷報表出貨，取最新一筆）
  // ②經銷通路且商品總表有「經銷價」欄 → 經銷價 ③商品總表「市價/建議售價」欄。
  // 都是含稅單價，如果表單選的是「未稅」會自動換算（÷1.05）。帶入後還是可以手動改。
  const priceHistory = useMemo(() => {
    const h = {};
    const put = (cust, code, price, date) => {
      if (!cust || !code || !(price > 0)) return;
      const k = `${cust}|${code}`;
      if (!h[k] || String(date) >= String(h[k].date)) h[k] = { price, date };
    };
    orders.forEach(o => (o.items || []).forEach(it => {
      const taxedUnit = o.taxType === 'untaxed' ? Math.round((it.price || 0) * 1.05) : (it.price || 0);
      put(o.customerId, it.code, taxedUnit, toISODate(o.date));
    }));
    erpRows.forEach(r => {
      const qty = Number(r[5]) || 0, amt = Number(r[6]) || 0;
      if (qty > 0 && amt > 0) put(String(r[0] || '').trim(), String(r[3] || '').trim(), Math.round(amt / qty), erpSalesDate(r));
    });
    return h;
  }, [orders, erpRows]);

  const suggestPrice = (p) => {
    const custId = customer?.id || editCustomerId;
    const hist = custId ? priceHistory[`${custId}|${p.code}`] : null;
    let taxed = 0, source = '';
    if (hist) { taxed = hist.price; source = `上次成交價（${hist.date}）`; }
    else if (channel === '經銷' && p.dealerPrice > 0) { taxed = p.dealerPrice; source = '商品總表經銷價'; }
    else if (p.retailPrice > 0) { taxed = p.retailPrice; source = '商品總表建議售價'; }
    if (!taxed) return { price: 0, source: '' };
    return { price: taxType === 'untaxed' ? Math.round(taxed / 1.05) : taxed, source };
  };

  const selectProduct = (idx, code) => {
    const p = productList.find(p => p.code === code);
    if (!p) return;
    const sug = suggestPrice(p);
    setItems(prev => prev.map((item,i) => i===idx
      ? (isFree(item)
          ? { ...item, code:p.code, name:p.name, cost:p.cost, price:0, priceSource:'' } // 公關品/退換不帶售價
          : { ...item, code:p.code, name:p.name, cost:p.cost,
              price: sug.price || (item.code === p.code ? item.price : 0),
              priceSource: sug.price ? sug.source : '' })
      : item));
  };

  const updateItem = (idx, field, val) =>
    setItems(prev => prev.map((item,i) => i===idx ? {...item,[field]:val} : item));

  const itemsTotal = items.reduce((s,item) => s + (isFree(item) ? 0 : (Number(item.price)||0)*(Number(item.qty)||0)), 0);
  const discountAmt = Math.max(0, Number(discount) || 0);
  const subtotal  = itemsTotal - discountAmt; // 折扣後的銷售金額（含稅或未稅，看上面選哪種）
  const itemCost  = item => Number(item.cost) || costMap[item.code] || 0;
  const totalCost = items.reduce((s,item) => s + itemCost(item)*(Number(item.qty)||0)*(isReturn(item) ? -1 : 1), 0);
  const gross     = subtotal - totalCost;

  const handleSelectCustomer = (c) => {
    if (c._new) {
      // 搜不到 → 開啟新增客戶 Modal，帶入已輸入的名稱
      setShowNewCustomer(true);
      setCustomerName(c.name);
    } else {
      setCustomer(c);
      setCustomerName(c.name);
    }
  };

  const handleNewCustomerSave = async (data) => {
    const newC = addCustomer(data);
    setCustomer(newC);
    setCustomerName(newC.name);
    setShowNewCustomer(false);
    // 開單頁快速建立新客戶，同樣要同步到 Google Sheets，不然這位客戶只存在這台電腦的畫面上。
    try {
      await writeCustomer(newC);
      writeChangeLog('新增客戶', `${newC.code} ${newC.name}（從開單頁建立）`);
    } catch(e) {
      console.warn('writeCustomer failed:', e.message);
      setSyncError(`新增客戶「${newC.name}」沒有同步到 Google Sheets（${e.message}）。這位客戶目前只存在你自己的畫面上，其他人看不到。`);
    }
  };

  // 搜尋 CRM 客戶帶出三個欄位
  const searchDealer = (field, val) => {
    if (!val || val.length < 1) { setDealerSuggestions([]); setShowDealerDrop(false); return; }
    const q = val.toLowerCase();
    const results = customers.filter(c => {
      if (field === 'short') return c.name?.toLowerCase().includes(q) || c.contact?.toLowerCase().includes(q);
      if (field === 'taxId') return c.taxId?.includes(val);
      if (field === 'title') return c.name?.toLowerCase().includes(q);
      return false;
    }).slice(0, 6);
    setDealerSuggestions(results);
    setShowDealerDrop(results.length > 0);
  };

  const selectDealer = (c) => {
    setDealerShort(c.shortName || c.name || '');
    setDealerTaxId(c.taxId || '');
    setDealerTitle(c.invoiceTitle || c.name || '');
    setCustomer(c);
    setCustomerName(c.name || '');
    setDealerSuggestions([]);
    setShowDealerDrop(false);
  };

  const handleSubmit = async () => {
    if (submitting) return;
    if (!customerName) { alert('請填入或選擇客戶'); return; }
    if (!orderDate) { alert('請選擇開立日期'); return; }
    const validItems = items.filter(i => i.code).map(i => (
      isReturn(i) ? { ...i, price: 0, qty: -Math.abs(Number(i.qty) || 0) }   // 退回入庫：存成負數量
      : isFree(i) ? { ...i, price: 0 } : i));
    if (discountAmt > itemsTotal) { alert('折扣金額不能大於商品金額'); return; }
    if (validItems.length === 0) { alert('請選擇至少一項商品'); return; }
    const order = {
      id:      editingId || `ORD-${Date.now()}`,
      date:    orderDate, // YYYY-MM-DD，跟銷貨/入庫查詢頁的日期篩選一致（見 utils/format.js 的說明）
      channel, note, taxType,
      dealerShort, dealerTaxId, dealerTitle,
      customer: customer?.name || customerName,
      customerId: customer?.id || editCustomerId || null,
      items:   validItems,
      discount: discountAmt,
      subtotal, totalCost, gross,
    };
    setSyncError('');
    setStockNotice('');
    setSubmitting(true);
    let notice = '';
    if (editingId) {
      const original = editingOriginal || orders.find(o => o.id === editingId);
      // 原本有扣過庫存的訂單：修改後也要記號，庫存只調「差額」（品項變多就多扣、變少就補回）。
      // 功能上線前的舊訂單當初沒扣，修改時也不動庫存，避免平白多扣。
      order.stockDeducted = !!original?.stockDeducted;
      const r = await updateOrder(editingId, order);
      setSubmitting(false);
      if (!r.ok) { setSyncError(r.error); await loadOrders(); return; }
      if (order.stockDeducted) {
        const next = unitsOf(order.items), prev = unitsOf(original.items);
        notice = await applyStock(diffUnits(next.units, prev.units), '修改訂單調整', `修改訂單 ${editingId}`);
        if (next.missing.length) notice += `　⚠ 這些代號商品總表找不到，沒有扣庫存：${next.missing.join('、')}`;
      }
      writeChangeLog('修改訂單', editingId, summarize(original), summarize({ ...order, taxedTotal: undefined }));
    } else {
      order.stockDeducted = true; // 新訂單一律扣庫存
      try {
        await writeOrder(order);
      } catch(e) {
        // 寫入失敗：左邊表單內容保留，不清空，讓使用者確認網路後直接再按一次
        console.warn('Sheets write failed:', e.message);
        setSubmitting(false);
        setSyncError(`訂單沒有存進 Google Sheets（${e.message}）。左邊填好的內容還保留著，請確認網路後再按一次「確認建立訂單」；如果一直失敗，請截圖這則訊息回報管理員。`);
        return;
      }
      setSubmitting(false);
      const u = unitsOf(order.items);
      notice = await applyStock(u.units, '手動開單扣庫存', `訂單 ${order.id}`);
      if (u.missing.length) notice += `　⚠ 這些代號商品總表找不到，沒有扣庫存：${u.missing.join('、')}`;
      writeChangeLog(copiedFrom ? '新增訂單（複製）' : '新增訂單', copiedFrom ? `${order.id}（複製自 ${copiedFrom}）` : order.id, '', summarize(order));
    }
    setStockNotice(notice);
    resetForm();
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
    await loadOrders();
    refreshCustomers().catch(() => {}); // 客戶的累計購買/訂單紀錄一起更新
    readProducts().then(list => setProductList(list)).catch(() => {}); // 庫存變了，重新讀
  };

  const q = search.trim().toLowerCase();
  const filteredOrders = q
    ? orders.filter(o => [o.id, o.customer, o.channel, o.date, o.dealerTitle, o.dealerShort]
        .some(v => String(v || '').toLowerCase().includes(q)))
    : orders;
  const orderCost = o => o.items.reduce((s, it) => s + (costMap[it.code] || 0) * it.qty, 0);

  return (
    <div>
      {syncError && (
        <div style={{ display:'flex', alignItems:'flex-start', gap:8, background:'rgba(255,0,110,0.08)', border:'1px solid rgba(255,0,110,0.3)', borderRadius:3, padding:'10px 14px', marginBottom:16, fontSize:14, color:'var(--pink)', lineHeight:1.6 }}>
          <span>⚠</span>
          <span style={{ flex:1 }}>{syncError}</span>
          <span style={{ cursor:'pointer', marginLeft:8 }} onClick={() => setSyncError('')}>✕</span>
        </div>
      )}
      {stockNotice && (
        <div style={{ display:'flex', alignItems:'flex-start', gap:8, background:'rgba(0,255,159,0.06)', border:'1px solid rgba(0,255,159,0.25)', borderRadius:3, padding:'10px 14px', marginBottom:16, fontSize:14, color:'var(--green)', lineHeight:1.6 }}>
          <span>▣</span>
          <span style={{ flex:1 }}>{stockNotice}</span>
          <span style={{ cursor:'pointer', marginLeft:8 }} onClick={() => setStockNotice('')}>✕</span>
        </div>
      )}
      <div className="grid-2">
        {/* 開單表單 */}
        <div className="card">
          <div className="card-title">
            {editingId ? <>修改訂單 <span style={{ color:'var(--yellow)' }}>{editingId}</span></> : '建立新訂單'}
            {editingId && (
              <button className="btn btn-ghost btn-sm" onClick={resetForm}>取消修改</button>
            )}
          </div>
          {copiedFrom && !editingId && (
            <div style={{ marginBottom:14, padding:'8px 12px', background:'rgba(0,245,255,0.06)', border:'1px solid rgba(0,245,255,0.25)', borderRadius:3, fontSize:14, color:'var(--cyan)', lineHeight:1.6, display:'flex', alignItems:'center', gap:8 }}>
              <span style={{ flex:1 }}>已複製訂單 {copiedFrom} 的內容，日期改成今天。確認無誤後按「確認建立訂單」會開一張新訂單，原本那張不受影響。</span>
              <button className="btn btn-ghost btn-sm" onClick={resetForm}>清空</button>
            </div>
          )}
          {editingId && (
            <div style={{ marginBottom:14, padding:'8px 12px', background:'rgba(245,196,0,0.08)', border:'1px solid rgba(245,196,0,0.3)', borderRadius:3, fontSize:14, color:'var(--yellow)', lineHeight:1.6 }}>
              正在修改既有訂單：改完按下方「儲存修改」會直接更新 Google Sheets 裡的這張訂單（訂單編號不變）。不想改了請按右上角「取消修改」。
            </div>
          )}

          {/* 管道 + 開立日期 + 客戶 */}
          <div className='order-channel-row' style={{ display:'flex', gap:10, marginBottom:14 }}>
            <div style={{ width:120, flexShrink:0 }}>
              <label className="form-label">銷售管道</label>
              <select className="form-input" value={channel} onChange={e => setChannel(e.target.value)}>
                {CHANNELS.map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div style={{ width:150, flexShrink:0 }}>
              <label className="form-label">開立日期</label>
              <input className="form-input" type="date" value={orderDate}
                onChange={e => setOrderDate(e.target.value)}/>
            </div>
            <div style={{ flex:1 }}>
              <label className="form-label">客戶 <span style={{ color:'var(--muted)', fontWeight:400 }}>（搜尋或建立）</span></label>
              <CustomerSearch
                value={customerName}
                onChange={setCustomerName}
                onSelect={handleSelectCustomer}
              />
            </div>
          </div>

          {/* 經銷商資訊（選經銷管道時顯示） */}
          {channel === '經銷' && (
            <div style={{ marginBottom:14, padding:12, background:'var(--bg3)', borderRadius:4, border:'1px solid var(--border)' }}>
              <div style={{ fontSize:14, color:'var(--cyan)', fontFamily:'var(--title)', letterSpacing:2, marginBottom:10 }}>經銷商資訊</div>
              <div className='dealer-grid' style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:10 }}>
                {/* 簡稱 */}
                <div style={{ position:'relative' }}>
                  <label className="form-label">簡稱（輸入帶出資料）</label>
                  <input className="form-input" placeholder="輸入簡稱搜尋..."
                    value={dealerShort}
                    onChange={e => { setDealerShort(e.target.value); searchDealer('short', e.target.value); }}
                    onFocus={() => dealerSuggestions.length > 0 && setShowDealerDrop(true)}
                  />
                  {showDealerDrop && (
                    <div style={{ position:'absolute', top:'100%', left:0, right:0, background:'var(--bg2)', border:'1px solid var(--border-strong)', borderRadius:4, zIndex:100, boxShadow:'0 8px 24px rgba(0,0,0,0.4)' }}>
                      {dealerSuggestions.map(c => (
                        <div key={c.id} onClick={() => selectDealer(c)}
                          style={{ padding:'8px 12px', cursor:'pointer', fontSize:13, borderBottom:'1px solid var(--border)' }}
                          onMouseOver={e => e.currentTarget.style.background='rgba(0,245,255,0.05)'}
                          onMouseOut={e => e.currentTarget.style.background='transparent'}>
                          <div style={{ fontWeight:600, color:'var(--text)' }}>{c.name}</div>
                          <div style={{ fontSize:11, color:'var(--muted)' }}>
                            {c.shortName && <span style={{ color:'var(--cyan)', marginRight:8 }}>{c.shortName}</span>}
                            {c.taxId && <span style={{ marginRight:8 }}>{c.taxId}</span>}
                            {c.invoiceTitle && c.invoiceTitle !== c.name && <span>{c.invoiceTitle}</span>}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                {/* 統編 */}
                <div>
                  <label className="form-label">統一編號</label>
                  <input className="form-input" placeholder="12345678"
                    value={dealerTaxId}
                    onChange={e => { setDealerTaxId(e.target.value); searchDealer('taxId', e.target.value); }}
                  />
                </div>
                {/* 抬頭 */}
                <div>
                  <label className="form-label">發票抬頭</label>
                  <input className="form-input" placeholder="公司名稱"
                    value={dealerTitle}
                    onChange={e => { setDealerTitle(e.target.value); searchDealer('title', e.target.value); }}
                  />
                </div>
              </div>
              {dealerTaxId && dealerTitle && (
                <div style={{ marginTop:8, fontSize:12, color:'var(--green)', letterSpacing:1 }}>
                  ✓ 發票開立：{dealerTitle}（{dealerTaxId}）
                </div>
              )}
            </div>
          )}

          {/* 已選客戶資訊 */}
          {customer && (
            <div style={{ marginBottom:14, padding:'8px 12px', background:'rgba(0,245,255,0.06)', border:'1px solid rgba(0,245,255,0.2)', borderRadius:4, display:'flex', justifyContent:'space-between', alignItems:'center' }}>
              <div>
                <span style={{ fontSize:17, color:'var(--cyan)', fontWeight:600 }}>{customer.name}</span>
                <span style={{ fontSize:14, color:'var(--muted)', marginLeft:10 }}>{customer.code} · {customer.phone}</span>
              </div>
              <div style={{ fontSize:17, color:'var(--muted)' }}>
                累計 {fmt.currency(customer.totalAmount)} · {customer.orders.length} 筆
                <button className="btn btn-ghost btn-sm" style={{ marginLeft:8 }}
                  onClick={() => { setCustomer(null); setCustomerName(''); }}>
                  ✕
                </button>
              </div>
            </div>
          )}

          {/* 品項表格 */}
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>商品</th>
                  <th style={{ width:96 }}>類型</th>
                  <th style={{ textAlign:'right', width:70 }}>數量</th>
                  <th style={{ textAlign:'right', width:100 }}>單價</th>
                  <th style={{ textAlign:'right', width:100 }}>小計</th>
                  <th style={{ width:36 }}></th>
                </tr>
              </thead>
              <tbody>
                {items.map((item, idx) => (
                  <tr key={idx} style={isFree(item) ? { background:'rgba(180,79,255,0.06)' } : undefined}>
                    <td style={{ minWidth:200 }}>
                      <select className="form-input" style={{ fontSize:18 }} value={item.code}
                        onChange={e => selectProduct(idx, e.target.value)}>
                        <option value="">-- 選擇商品 --</option>
                        {/* 修改舊訂單時，如果這個代號現在已經不在商品總表裡，還是要顯示出來，不然下拉選單會變空白、存檔時品項被吃掉 */}
                        {item.code && !productList.some(p => p.code === item.code) && (
                          <option value={item.code}>{item.code}  {item.name}（商品總表找不到）</option>
                        )}
                        {sellable.map(p => <option key={p.code} value={p.code}>{p.code}  {p.name}</option>)}
                      </select>
                      {item.priceSource && (
                        <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>單價帶入：{item.priceSource}</div>
                      )}
                    </td>
                    <td>
                      <select className="form-input" style={{ fontSize:15, padding:'4px 6px' }} value={item.kind || '一般'}
                        onChange={e => setItemKind(idx, e.target.value)}
                        title="公關品／退換：免費給出去，單價固定 0，但一樣扣庫存">
                        {ITEM_KINDS.map(k => <option key={k} value={k}>{k}</option>)}
                      </select>
                    </td>
                    <td>
                      <input className="form-input" type="number" min="1" value={item.qty}
                        style={{ textAlign:'right', width:60 }}
                        onChange={e => updateItem(idx,'qty',Number(e.target.value))}/>
                    </td>
                    <td>
                      <input className="form-input" type="number" value={isFree(item) ? 0 : item.price}
                        disabled={isFree(item)}
                        style={{ textAlign:'right', color:'var(--cyan)', width:80, opacity: isFree(item) ? 0.5 : 1 }}
                        onChange={e => updateItem(idx,'price',Number(e.target.value))}/>
                    </td>
                    <td className="td-right td-mono" style={{ color: isReturn(item) ? 'var(--yellow)' : isFree(item) ? 'var(--purple)' : 'var(--green)' }}>
                      {isReturn(item) ? '加回庫存' : isFree(item) ? '免費' : fmt.currency((item.price||0)*(item.qty||0))}
                    </td>
                    <td style={{ textAlign:'center' }}>
                      {items.length > 1 && (
                        <span style={{ color:'var(--muted)', cursor:'pointer', fontSize:20 }}
                          onClick={() => removeItem(idx)}>✕</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div style={{ marginTop:10, display:'flex', gap:8, flexWrap:'wrap' }}>
            <button className="btn btn-ghost btn-sm" onClick={() => addItem('一般')}>＋ 新增品項</button>
            <button className="btn btn-ghost btn-sm" style={{ color:'var(--purple)' }} onClick={() => addItem('公關品')}>＋ 公關品</button>
            <button className="btn btn-ghost btn-sm" style={{ color:'var(--purple)' }} onClick={() => addItem('退換')}>＋ 退換商品</button>
            <button className="btn btn-ghost btn-sm" style={{ color:'var(--yellow)' }} onClick={() => addItem('退回入庫')}>＋ 退回入庫</button>
          </div>
          <div style={{ fontSize:12, color:'var(--muted)', marginTop:4, lineHeight:1.7 }}>
            ◈ 公關品／退換：免費給出去的貨，單價固定 0、不算營收，但會扣庫存、成本算進銷貨成本<br/>
            ◈ 退回入庫：客人退回來的貨，數量照實際退回填正數，建立訂單時會加回庫存（銷貨成本、銷售數量也會跟著扣回）
          </div>

          <div style={{ marginTop:12, display:'flex', alignItems:'center', gap:10 }}>
            <label className="form-label" style={{ margin:0, whiteSpace:'nowrap' }}>折扣金額</label>
            <input className="form-input" type="number" min="0" value={discount || ''} placeholder="0"
              style={{ textAlign:'right', width:140, color:'var(--pink)' }}
              onChange={e => setDiscount(Number(e.target.value) || 0)}/>
            <span style={{ fontSize:12, color:'var(--muted)' }}>（跟下面選的含稅／未稅同一個基礎，從商品金額直接扣掉）</span>
          </div>

          <div style={{ marginTop:12 }}>
            <label className="form-label">備註</label>
            <input className="form-input" placeholder="折扣說明、交貨條件等" value={note}
              onChange={e => setNote(e.target.value)}/>
          </div>

          {/* 含稅/未稅切換 */}
          <div style={{ marginTop:14, display:'flex', alignItems:'center', gap:8 }}>
            <span style={{ fontSize:14, color:'var(--muted)' }}>金額類型：</span>
            {[
              { id:'taxed',   label:'含稅（含 5% 營業稅）' },
              { id:'untaxed', label:'未稅' },
            ].map(t => (
              <button key={t.id}
                className={`btn btn-sm ${taxType===t.id ? 'btn-primary' : 'btn-ghost'}`}
                onClick={() => setTaxType(t.id)}>
                {t.label}
              </button>
            ))}
          </div>

          {/* 金額摘要 */}
          <div style={{ marginTop:10, padding:14, background:'var(--bg3)', borderRadius:4, border:'1px solid var(--border)' }}>
            {discountAmt > 0 && (
              <>
                <div style={{ display:'flex', justifyContent:'space-between', marginBottom:6, fontSize:14 }}>
                  <span style={{ color:'var(--muted)' }}>商品金額</span>
                  <span style={{ fontFamily:'var(--mono)' }}>{fmt.currency(itemsTotal)}</span>
                </div>
                <div style={{ display:'flex', justifyContent:'space-between', marginBottom:8, fontSize:14 }}>
                  <span style={{ color:'var(--muted)' }}>折扣</span>
                  <span style={{ fontFamily:'var(--mono)', color:'var(--pink)' }}>−{fmt.currency(discountAmt)}</span>
                </div>
              </>
            )}
            {taxType === 'taxed' ? (
              <>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8, fontSize:14, flexWrap:'wrap', gap:4 }}>
                  <span style={{ color:'var(--muted)' }}>含稅銷售金額</span>
                  <span style={{ color:'var(--cyan)', fontFamily:'var(--mono)', fontWeight:600, whiteSpace:'nowrap' }}>{fmt.currency(subtotal)}</span>
                </div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8, fontSize:14, flexWrap:'wrap', gap:4 }}>
                  <span style={{ color:'var(--muted)' }}>　└ 未稅金額</span>
                  <span style={{ color:'var(--muted)', fontFamily:'var(--mono)' }}>{fmt.currency(Math.round(subtotal / 1.05))}</span>
                </div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8, fontSize:14, flexWrap:'wrap', gap:4 }}>
                  <span style={{ color:'var(--muted)' }}>　└ 稅額（5%）</span>
                  <span style={{ color:'var(--muted)', fontFamily:'var(--mono)' }}>{fmt.currency(Math.round(subtotal - subtotal / 1.05))}</span>
                </div>
              </>
            ) : (
              <>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8, fontSize:14, flexWrap:'wrap', gap:4 }}>
                  <span style={{ color:'var(--muted)' }}>未稅銷售金額</span>
                  <span style={{ color:'var(--cyan)', fontFamily:'var(--mono)', fontWeight:600, whiteSpace:'nowrap' }}>{fmt.currency(subtotal)}</span>
                </div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8, fontSize:14, flexWrap:'wrap', gap:4 }}>
                  <span style={{ color:'var(--muted)' }}>　└ 含稅金額（+5%）</span>
                  <span style={{ color:'var(--muted)', fontFamily:'var(--mono)' }}>{fmt.currency(Math.round(subtotal * 1.05))}</span>
                </div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8, fontSize:14, flexWrap:'wrap', gap:4 }}>
                  <span style={{ color:'var(--muted)' }}>　└ 稅額（5%）</span>
                  <span style={{ color:'var(--muted)', fontFamily:'var(--mono)' }}>{fmt.currency(Math.round(subtotal * 0.05))}</span>
                </div>
              </>
            )}
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:8, fontSize:16, borderTop:'1px solid var(--border)', paddingTop:8, marginTop:4 }}>
              <span style={{ color:'var(--muted)' }}>銷貨成本</span>
              <span style={{ color:'var(--pink)', fontFamily:'var(--mono)', fontWeight:600 }}>{fmt.currency(totalCost)}</span>
            </div>
            <div style={{ display:'flex', justifyContent:'space-between', borderTop:'1px solid var(--border)', paddingTop:10, fontSize:19 }}>
              <span style={{ color:'var(--text)', fontFamily:'var(--title)', letterSpacing:1 }}>毛利</span>
              <span style={{ color:'var(--green)', fontFamily:'var(--mono)', fontWeight:700, fontSize:20 }}>{fmt.currency(gross)}</span>
            </div>
          </div>

          <button className="btn btn-primary" style={{ width:'100%', marginTop:14, justifyContent:'center', fontSize:18, opacity: submitting ? 0.6 : 1 }}
            onClick={handleSubmit} disabled={submitting}>
            {submitting ? '儲存中…' : saved ? '✓ 已存進 Google Sheets' : editingId ? '◈ 儲存修改' : '◈ 確認建立訂單'}
          </button>
        </div>

        {/* 訂單紀錄（全部歷史，從 Google Sheets 的 orders 分頁讀取） */}
        <div className="card">
          <div className="card-title">
            手動開單紀錄（全部歷史） <span>{filteredOrders.length} 筆</span>
            <button className="btn btn-ghost btn-sm" onClick={loadOrders} disabled={ordersLoading}>
              {ordersLoading ? '讀取中…' : '↻ 重新整理'}
            </button>
          </div>
          <input className="form-input" style={{ marginBottom:12 }}
            placeholder="搜尋訂單編號／客戶／管道／日期…"
            value={search} onChange={e => { setSearch(e.target.value); setShowCount(PAGE_SIZE); }}/>

          {ordersError ? (
            <div style={{ padding:'14px', color:'var(--pink)', fontSize:15, lineHeight:1.6 }}>⚠ {ordersError}</div>
          ) : ordersLoading && orders.length === 0 ? (
            <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)' }}>讀取中…</div>
          ) : filteredOrders.length === 0 ? (
            <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)' }}>
              <div style={{ fontSize:30, marginBottom:10 }}>◻</div>
              <div style={{ fontSize:18, letterSpacing:1 }}>{q ? '沒有符合搜尋的訂單' : '尚無手動訂單'}</div>
              {!q && <div style={{ fontSize:14, marginTop:6 }}>在左側填寫並確認建立</div>}
            </div>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>訂單編號</th><th>日期</th><th>管道</th>
                    <th>客戶</th>
                    <th style={{ textAlign:'right' }}>含稅金額</th>
                    <th style={{ textAlign:'right' }}>毛利</th>
                    <th style={{ width:200 }}></th>
                  </tr>
                </thead>
                <tbody>
                  {filteredOrders.slice(0, showCount).map(o => (
                    <tr key={o.id} onClick={() => startEdit(o)} title="點一下這張訂單，帶到左邊修改"
                      style={{ cursor:'pointer', background: editingId === o.id ? 'rgba(245,196,0,0.08)' : undefined }}>
                      <td className="td-mono" style={{ color:'var(--cyan)', fontSize:17 }}>{o.id}</td>
                      <td style={{ fontSize:17, color:'var(--muted)', whiteSpace:'nowrap' }}>{o.date}</td>
                      <td><span className="badge badge-blue">{o.channel}</span></td>
                      <td style={{ fontSize:18 }}>{o.customer}</td>
                      <td className="td-right td-mono" style={{ color:'var(--cyan)', fontWeight:600 }}>{fmt.currency(o.taxedTotal)}</td>
                      <td className="td-right td-mono" style={{ color:'var(--green)', fontWeight:600 }}>{fmt.currency(o.taxedTotal - orderCost(o))}</td>
                      <td style={{ textAlign:'center', whiteSpace:'nowrap' }} onClick={e => e.stopPropagation()}>
                        <button className="btn btn-ghost btn-sm" onClick={() => printInvoice(o)}>銷貨單</button>
                        <button className="btn btn-ghost btn-sm" style={{ marginLeft:6, color:'var(--cyan)' }}
                          title="把這張訂單的內容複製到左邊，開成一張新訂單" onClick={() => startCopy(o)}>複製</button>
                        <button className="btn btn-ghost btn-sm" style={{ marginLeft:6, color:'var(--pink)' }}
                          disabled={busyId === o.id} onClick={() => handleDelete(o)}>
                          {busyId === o.id ? '刪除中…' : '刪除'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filteredOrders.length > showCount && (
                <button className="btn btn-ghost btn-sm" style={{ width:'100%', marginTop:10, justifyContent:'center' }}
                  onClick={() => setShowCount(n => n + PAGE_SIZE)}>
                  顯示更多（還有 {filteredOrders.length - showCount} 筆）
                </button>
              )}
            </div>
          )}

          <div style={{ marginTop:14, padding:12, background:'rgba(0,245,255,0.03)', border:'1px solid var(--border)', borderRadius:3, fontSize:17, color:'var(--muted)', lineHeight:2 }}>
            ◈ 手動開單後數據自動計入銷貨總表和損益表<br/>
            ◈ 點一下右邊任一筆訂單，可以帶回左邊修改；按「複製」會把內容帶到左邊開一張新訂單；按「刪除」會直接從 Google Sheets 移除<br/>
            ◈ 建立訂單會自動扣庫存（套組依套組成分表拆成單品扣）；修改訂單只調差額，刪除訂單會補回（這個功能上線前開的舊訂單當初沒扣，修改/刪除也不會動庫存）<br/>
            ◈ 可以加「公關品」「退換商品」（免費、照樣扣庫存）、「退回入庫」（加回庫存）和整張訂單的「折扣金額」<br/>
            ◈ 選商品會自動帶入單價：這個客戶上次的成交價 → 經銷價 → 建議售價（商品總表），帶入後可以再改<br/>
            ◈ 選擇已存在的客戶，訂單紀錄自動串連到 CRM<br/>
            ◈ 搜不到客戶時，系統會引導建立新客戶<br/>
            ◈ 按右側「銷貨單」會開啟列印視窗，印表機選單選「另存為 PDF」即可存成 PDF 電子單據
          </div>
        </div>
      </div>

      {/* 新增客戶 Modal（從開單頁觸發） */}
      {showNewCustomer && (
        <CustomerModal
          initial={{ name:customerName }}
          onSave={handleNewCustomerSave}
          onClose={() => setShowNewCustomer(false)}
        />
      )}
    </div>
  );
}